{
  "decision-date-a-legend-reading-between-proofs": "WITH ranked AS (SELECT i.impression_id, n.reading, n.source_id, ROW_NUMBER() OVER (PARTITION BY i.impression_id ORDER BY n.note_day DESC, (n.plate_code IS NOT NULL) DESC, n.source_id COLLATE BINARY ASC) AS rn FROM impressions AS i LEFT JOIN proof_notes AS n ON n.glyph = i.glyph AND n.note_day <= i.print_day AND (n.plate_code IS NULL OR n.plate_code = i.plate_code)) SELECT impression_id, reading, source_id FROM ranked WHERE rn = 1 ORDER BY impression_id ASC",
  "decision-dead-heat-purse-apportionment": "WITH classified AS (SELECT squad, RANK() OVER (ORDER BY official_ms) AS finish_place, COUNT(*) OVER (PARTITION BY official_ms) AS tie_size, ROW_NUMBER() OVER (PARTITION BY official_ms ORDER BY squad COLLATE BINARY) AS tie_order FROM finish_log WHERE official_ms IS NOT NULL), pooled AS (SELECT c.*, COALESCE((SELECT SUM(p.prize_cents) FROM prize_slot AS p WHERE p.slot_no >= c.finish_place AND p.slot_no < c.finish_place + c.tie_size), 0) AS pool_cents FROM classified AS c) SELECT squad, finish_place, pool_cents / tie_size + (tie_order <= pool_cents % tie_size) AS payout_cents FROM pooled ORDER BY finish_place ASC, squad COLLATE BINARY ASC",
  "decision-dispatch-recovery-blocks": "SELECT a.offer_code AS a_code, b.offer_code AS b_code, a.fee + b.fee AS fee_cents, a.fee + b.fee - d.budget_cents AS over_budget_cents FROM block_offer AS a CROSS JOIN block_offer AS b CROSS JOIN depot_limit AS d WHERE a.vendor = 'A' AND b.vendor = 'B' AND a.crates + b.crates >= d.backlog AND a.hours_used + b.hours_used <= d.crew_hours ORDER BY fee_cents ASC, a.offer_code COLLATE BINARY ASC, b.offer_code COLLATE BINARY ASC LIMIT 1",
  "decision-display-tray-stock-writedown": "SELECT m.shop_code, m.memo_day AS adoption_day, COALESCE(SUM(c.units_held * MAX(c.book_cents - c.recovery_cents, 0)), 0) AS write_down_cents, m.source_id FROM shop_memo AS m LEFT JOIN opening_count AS c ON c.shop_code = m.shop_code AND c.count_day = m.memo_day WHERE m.action_code = 'launch' GROUP BY m.shop_code, m.memo_day, m.source_id ORDER BY m.shop_code ASC"
}
